+++ b/tests/unit/orchestration/modules/provider-claude-agent-sdk/agent-host/agent-stream.test.ts
@@ -0,0 +1,120 @@
+import { afterEach, describe, expect, setSystemTime, test } from "bun:test";
+import type Anthropic from "@anthropic-ai/sdk";
+import type { AgentRows, SignedBlock } from "../../../../../../src/orchestration/modules/provider-claude-agent-sdk/agent-host/agent-file.js";
+import { hostedStreamEvents, type HostedAnswer, type StepEvent } from "../../../../../../src/orchestration/modules/provider-claude-agent-sdk/agent-host/agent-stream.js";
+import type { HostStepItem } from "../../../../../../src/orchestration/modules/provider-claude-agent-sdk/agent-host/host-gate.js";
+import { LlmStreamError } from "../../../../../../src/orchestration/agent-runtime/llm/errors.js";
+
+const THINKING: SignedBlock = { type: "thinking", thinking: "Plan it.", signature: "sig-1" };
+const REDACTED: SignedBlock = { type: "redacted_thinking", data: "opaque" };
+const STOP: HostStepItem = { kind: "stop", stopReason: "end_turn", usage: { input_tokens: 3, output_tokens: 4, cache_read_input_tokens: 0, cache_creation_input_tokens: 0 } };
+const SERVICE_FAILURE = new Error("529 overloaded");
+
+/** The engine's rows as its transcript cursor writes them: it holds every row of a response until the response's stop
+ *  chunk, so a test writes them only once the stream took that chunk. */
+function engineRows() {
+  const signed: SignedBlock[] = [];
+  const rows: AgentRows = { read: () => signed };
+  return { rows, write: (...blocks: SignedBlock[]) => { signed.push(...blocks); } };
+}
+
+/** A step whose chunks the test sends one at a time, as the host gate hands them on. */
+function liveStep() {
+  const queued: StepEvent[] = [];
+  let wake: (() => void) | undefined;
+  let taken = 0;
+  const send = (event: StepEvent) => {
+    queued.push(event);
+    wake?.();
+  };
+  async function* events(): AsyncGenerator<StepEvent> {
+    while (true) {
+      while (taken < queued.length) {
+        const event = queued[taken];
+        taken += 1;
+        if (event !== undefined) yield event;
+      }
+      await new Promise<void>((resolve) => { wake = resolve; });
+    }
+  }
+  return { events: events(), send, item: (item: HostStepItem) => { send({ kind: "item", item }); }, taken: () => taken };
+}
+
+function collect(events: AsyncIterable<StepEvent>, rows: AgentRows) {
+  const out: Anthropic.RawMessageStreamEvent[] = [];
+  const answers: HostedAnswer[] = [];
+  let progress = 0;
+  const ended = (async () => {
+    for await (const event of hostedStreamEvents(events, rows, 0, "claude-test", async () => SERVICE_FAILURE, (answer) => { answers.push(answer); }, () => { progress += 1; })) out.push(event);
+  })();
+  return { out, answers, progress: () => progress, ended };
+}
+
+const settle = () => Bun.sleep(60);
+
+afterEach(() => { setSystemTime(); });
+
+describe("the hosted stream", () => {
+  test("streams a response that writes long after its thinking, holding later blocks until the engine writes the rows after the stop chunk, in Anthropic order", async () => {
+    const step = liveStep();
+    const engine = engineRows();
+    const stream = collect(step.events, engine.rows);
+    step.item({ kind: "thinking", index: 0, text: "Plan" });
+    step.item({ kind: "text", index: 2, text: "Hello" });
+    // The model writes for a minute after it thinks.
+    setSystemTime(new Date(Date.now() + 61_000));
+    step.item({ kind: "text", index: 2, text: " world" });
+    step.item(STOP);
+    await settle();
+    // Every chunk reached the stream although no row was written while the model wrote.
+    expect(step.taken()).toBe(4);
+    engine.write(THINKING, REDACTED);
+    await stream.ended;
+    expect(stream.out.map((event) => event.type === "content_block_delta" ? `${event.type}:${event.index}:${event.delta.type}` : "index" in event ? `${event.type}:${event.index}` : event.type)).toEqual([
+      "message_start",
+      "content_block_start:0", "content_block_delta:0:thinking_delta", "content_block_delta:0:thinking_delta", "content_block_delta:0:signature_delta", "content_block_stop:0",
+      "content_block_start:1", "content_block_stop:1",
+      "content_block_start:2", "content_block_delta:2:text_delta", "content_block_delta:2:text_delta", "content_block_stop:2",
+      "message_delta", "message_stop",
+    ]);
+    expect(stream.answers).toEqual([{ message: { role: "assistant", content: [THINKING, REDACTED, { type: "text", text: "Hello world" }] }, stopReason: "end_turn" }]);
+  });
+
+  test("reports each chunk it holds back as progress, and none while the model sends nothing, so a stalled response still stalls", async () => {
+    const step = liveStep();
+    const stream = collect(step.events, engineRows().rows);
+    step.item({ kind: "thinking", index: 0, text: "Plan" });
+    await settle();
+    expect(stream.progress()).toBe(0);
+    step.item({ kind: "text", index: 1, text: "Hello" });
+    step.item({ kind: "text", index: 1, text: " world" });
+    await settle();
+    expect(stream.progress()).toBe(2);
+    await settle();
+    expect(stream.progress()).toBe(2);
+  });
+
+  test("a row that the engine still has not written a minute after the stop chunk fails transient", async () => {
+    const step = liveStep();
+    const engine = engineRows();
+    const stream = collect(step.events, engine.rows);
+    step.item({ kind: "thinking", index: 0, text: "Plan" });
+    step.item({ kind: "text", index: 1, text: "Hello" });
+    step.item(STOP);
+    await settle();
+    expect(stream.progress()).toBeGreaterThan(2);
+    setSystemTime(new Date(Date.now() + 61_000));
+    const error = await stream.ended.then(() => undefined, (failure: unknown) => failure);
+    expect(error).toBeInstanceOf(LlmStreamError);
+    expect(error).toMatchObject({ kind: "transient", message: expect.stringContaining("wrote no row") });
+  });
+
+  test("a step that ends without its stop chunk fails with the service's answer, even while it waits for a row", async () => {
+    const step = liveStep();
+    const stream = collect(step.events, engineRows().rows);
+    step.item({ kind: "thinking", index: 0, text: "Plan" });
+    step.item({ kind: "text", index: 1, text: "Hello" });
+    step.send({ kind: "done" });
+    expect(await stream.ended.then(() => undefined, (failure: unknown) => failure)).toBe(SERVICE_FAILURE);
+  });
+});

