+use react::*;
+use std::cell::RefCell;
+
+#[test]
+fn input_and_compute_values_propagate() {
+    let mut r = Reactor::new();
+    let a = r.create_input(1);
+    let b = r
+        .create_compute(&[CellId::Input(a)], |v| v[0] + 1)
+        .unwrap();
+    let c = r
+        .create_compute(&[CellId::Input(a), CellId::Compute(b)], |v| v[0] * v[1])
+        .unwrap();
+    assert_eq!(r.value(CellId::Compute(c)), Some(2));
+    assert!(r.set_value(a, 3));
+    assert_eq!(r.value(CellId::Input(a)), Some(3));
+    assert_eq!(r.value(CellId::Compute(b)), Some(4));
+    assert_eq!(r.value(CellId::Compute(c)), Some(12));
+}
+
+#[test]
+fn nonexistent_dependency_is_rejected() {
+    let mut other = Reactor::new();
+    let foreign = other.create_input(0);
+    let mut r: Reactor<i32> = Reactor::new();
+    assert_eq!(
+        r.create_compute(&[CellId::Input(foreign)], |_| 0),
+        Err(CellId::Input(foreign))
+    );
+    assert!(!r.set_value(foreign, 1));
+    assert_eq!(r.value(CellId::Input(foreign)), None);
+}
+
+#[test]
+fn callbacks_fire_once_with_final_value_only_on_change() {
+    let seen = RefCell::new(Vec::new());
+    let mut r = Reactor::new();
+    let input = r.create_input(1);
+    let plus_one = r.create_compute(&[CellId::Input(input)], |v| v[0] + 1).unwrap();
+    let minus_one = r.create_compute(&[CellId::Input(input)], |v| v[0] - 1).unwrap();
+    let output = r
+        .create_compute(
+            &[CellId::Compute(plus_one), CellId::Compute(minus_one)],
+            |v| v[0] * v[1],
+        )
+        .unwrap();
+    let parity = r
+        .create_compute(&[CellId::Input(input)], |v| v[0] % 2)
+        .unwrap();
+    r.add_callback(output, |v| seen.borrow_mut().push(("out", v)))
+        .unwrap();
+    let cb = r
+        .add_callback(parity, |v| seen.borrow_mut().push(("parity", v)))
+        .unwrap();
+    assert!(r.set_value(input, 3));
+    assert!(r.set_value(input, 4));
+    assert_eq!(r.remove_callback(parity, cb), Ok(()));
+    assert_eq!(
+        r.remove_callback(parity, cb),
+        Err(RemoveCallbackError::NonexistentCallback)
+    );
+    assert!(r.set_value(input, 5));
+    drop(r);
+    assert_eq!(
+        seen.into_inner(),
+        vec![("out", 8), ("out", 15), ("parity", 0), ("out", 24)]
+    );
+}
+
+#[test]
+fn removing_callback_from_nonexistent_cell_errors() {
+    let mut other: Reactor<i32> = Reactor::new();
+    let i = other.create_input(1);
+    let c = other.create_compute(&[CellId::Input(i)], |v| v[0]).unwrap();
+    let cb = other.add_callback(c, |_| ()).unwrap();
+    let mut r: Reactor<i32> = Reactor::new();
+    assert!(r.add_callback(c, |_| ()).is_none());
+    assert_eq!(
+        r.remove_callback(c, cb),
+        Err(RemoveCallbackError::NonexistentCell)
+    );
+}

