@@ -0,0 +1,42 @@
+import { TemplateError, type TemplateNode, type TemplateToken } from "./types.js";
+
+type BlockNode = Extract<TemplateNode, { children: TemplateNode[] }>;
+
+/**
+ * Builds the nested block tree from tokens. Each closing tag must match the innermost
+ * open block; an unexpected or mismatched close throws TemplateError at the closing
+ * token's position, and an unclosed block throws at its opening token's position.
+ */
+export function parse(tokens: readonly TemplateToken[]): TemplateNode[] {
+  const root: TemplateNode[] = [];
+  const stack: BlockNode[] = [];
+  const current = () => stack.at(-1)?.children ?? root;
+  for (const token of tokens) {
+    switch (token.kind) {
+      case "text":
+      case "variable":
+        current().push(token);
+        break;
+      case "open": {
+        const block: BlockNode = { kind: token.block, path: token.path, position: token.position, children: [] };
+        current().push(block);
+        stack.push(block);
+        break;
+      }
+      case "close": {
+        const innermost = stack.pop();
+        if (!innermost) throw new TemplateError(`Unexpected closing ${token.block}`, token.position);
+        if (innermost.kind !== token.block) {
+          throw new TemplateError(
+            `Mismatched closing ${token.block} for ${innermost.kind} opened at position ${innermost.position}`,
+            token.position,
+          );
+        }
+        break;
+      }
+    }
+  }
+  const unclosed = stack.at(-1);
+  if (unclosed) throw new TemplateError(`Unclosed ${unclosed.kind}`, unclosed.position);
+  return root;
+}
