+import { parse } from "./parser.js";
 import { tokenize } from "./tokenizer.js";
-import type { TemplateContext } from "./types.js";
+import type { TemplateContext, TemplateNode } from "./types.js";

-export function render(template: string, _context: TemplateContext = {}): string {
-  return tokenize(template)
-    .map((token) => token.kind === "text" ? token.value : "")
-    .join("");
+/**
+ * Renders a template against a context. `{{path}}` is HTML-escaped, `{{{path}}}` is raw,
+ * `{{#if path}}` uses JavaScript truthiness, and `{{#each path}}` repeats its body for each
+ * array item with that item as the body's context. Missing, null, and undefined values
+ * render as empty text. Throws TemplateError for malformed or unbalanced tags.
+ */
+export function render(template: string, context: TemplateContext = {}): string {
+  return renderNodes(parse(tokenize(template)), context);
+}
+
+function renderNodes(nodes: readonly TemplateNode[], scope: unknown): string {
+  return nodes.map((node) => renderNode(node, scope)).join("");
+}
+
+function renderNode(node: TemplateNode, scope: unknown): string {
+  switch (node.kind) {
+    case "text":
+      return node.value;
+    case "variable": {
+      const value = resolve(scope, node.path);
+      const text = value === null || value === undefined ? "" : String(value);
+      return node.escaped ? escapeHtml(text) : text;
+    }
+    case "if":
+      return resolve(scope, node.path) ? renderNodes(node.children, scope) : "";
+    case "each": {
+      const items = resolve(scope, node.path);
+      return Array.isArray(items) ? items.map((item) => renderNodes(node.children, item)).join("") : "";
+    }
+  }
+}
+
+function resolve(scope: unknown, path: string): unknown {
+  let value = scope;
+  for (const segment of path.split(".")) {
+    if (value === null || value === undefined) return undefined;
+    value = (value as Record<string, unknown>)[segment];
+  }
+  return value;
+}
+
+function escapeHtml(text: string): string {
+  return text
+    .replaceAll("&", "&amp;")
+    .replaceAll("<", "&lt;")
+    .replaceAll(">", "&gt;")
+    .replaceAll('"', "&quot;")
+    .replaceAll("'", "&#39;");
 }
