@@ -0,0 +1,137 @@
+import { afterEach, describe, expect, setSystemTime, test } from "bun:test";
+import type Anthropic from "@anthropic-ai/sdk";
+import type { AgentRows, SignedBlock } from "../../../../../../src/orchestration/modules/provider-claude-agent-sdk/agent-host/agent-file.js";
+import { hostedStreamEvents, type StepEvent } from "../../../../../../src/orchestration/modules/provider-claude-agent-sdk/agent-host/agent-stream.js";
+import type { HostStepItem } from "../../../../../../src/orchestration/modules/provider-claude-agent-sdk/agent-host/host-gate.js";
+
+/** The step's events as the host gate hands them on, pushed by the test while the stream reads them. */
+function channel() {
+  const queued: StepEvent[] = [];
+  let wake: (() => void) | undefined;
+  const push = (event: StepEvent) => {
+    queued.push(event);
+    wake?.();
+  };
+  const events: AsyncIterable<StepEvent> = {
+    async *[Symbol.asyncIterator]() {
+      while (true) {
+        const event = queued.shift();
+        if (event === undefined) {
+          await new Promise<void>((resolve) => { wake = resolve; });
+          continue;
+        }
+        yield event;
+        if (event.kind === "done") return;
+      }
+    },
+  };
+  return { events, item: (item: HostStepItem) => { push({ kind: "item", item }); }, done: () => { push({ kind: "done" }); } };
+}
+
+/** An agent file whose rows the test writes. */
+function agentRows() {
+  const signed: SignedBlock[] = [];
+  const rows: AgentRows = { read: () => signed };
+  return { rows, write: (block: SignedBlock) => { signed.push(block); } };
+}
+
+const SERVICE_ANSWER = new Error("529 overloaded");
+const STOP: HostStepItem = { kind: "stop", stopReason: "end_turn", usage: null };
+
+/** Streams the step, counting the progress that the stream reports, and settles with its events or its failure. */
+function streamed(events: AsyncIterable<StepEvent>, rows: AgentRows) {
+  let progress = 0;
+  const received: Anthropic.RawMessageStreamEvent[] = [];
+  const settled = (async () => {
+    for await (const event of hostedStreamEvents(events, rows, 0, "claude-test", async () => SERVICE_ANSWER, () => {}, () => { progress += 1; })) received.push(event);
+    return received;
+  })();
+  const failure = settled.then(() => undefined, (error: unknown) => error);
+  return { settled, failure, received, progress: () => progress };
+}
+
+/** Lets the stream poll the agent file a few times. */
+const polls = () => Bun.sleep(100);
+/** Moves the clock past any bound on the wait for a row. */
+const muchLater = () => { setSystemTime(new Date(Date.now() + 10 * 60_000)); };
+
+afterEach(() => { setSystemTime(); });
+
+describe("hostedStreamEvents", () => {
+  test("streams a response that writes long after its thinking, whose row the engine writes after the stop chunk", async () => {
+    const step = channel();
+    const file = agentRows();
+    const stream = streamed(step.events, file.rows);
+    step.item({ kind: "thinking", index: 0, text: "Let me " });
+    step.item({ kind: "text", index: 1, text: "First" });
+    await polls();
+    muchLater();
+    step.item({ kind: "text", index: 1, text: " second" });
+    await polls();
+    muchLater();
+    step.item(STOP);
+    await polls();
+    muchLater();
+    file.write({ type: "thinking", thinking: "Let me think", signature: "sig" });
+    const events = await stream.settled;
+    expect(events.map((event) => [event.type, "delta" in event ? event.delta : undefined, "index" in event ? event.index : undefined])).toEqual([
+      ["message_start", undefined, undefined],
+      ["content_block_start", undefined, 0],
+      ["content_block_delta", { type: "thinking_delta", thinking: "Let me " }, 0],
+      ["content_block_delta", { type: "thinking_delta", thinking: "think" }, 0],
+      ["content_block_delta", { type: "signature_delta", signature: "sig" }, 0],
+      ["content_block_stop", undefined, 0],
+      ["content_block_start", undefined, 1],
+      ["content_block_delta", { type: "text_delta", text: "First" }, 1],
+      ["content_block_delta", { type: "text_delta", text: " second" }, 1],
+      ["content_block_stop", undefined, 1],
+      ["message_delta", expect.objectContaining({ stop_reason: "end_turn" }), undefined],
+      ["message_stop", undefined, undefined],
+    ]);
+  });
+
+  test("reports each chunk that it holds back while a row is pending, and no progress while chunks stop", async () => {
+    const step = channel();
+    const file = agentRows();
+    const stream = streamed(step.events, file.rows);
+    step.item({ kind: "thinking", index: 0, text: "Hmm" });
+    step.item({ kind: "text", index: 1, text: "A" });
+    await polls();
+    expect(stream.progress()).toBe(0);
+    step.item({ kind: "text", index: 1, text: "B" });
+    step.item({ kind: "text", index: 1, text: "C" });
+    await polls();
+    expect(stream.progress()).toBe(2);
+    expect(stream.received.map((event) => event.type)).toEqual(["message_start", "content_block_start", "content_block_delta"]);
+    file.write({ type: "thinking", thinking: "Hmm", signature: "sig" });
+    await polls();
+    step.item(STOP);
+    await stream.settled;
+    expect(stream.progress()).toBe(2);
+  });
+
+  test("fails transient when the row is still missing after the stop chunk", async () => {
+    const step = channel();
+    const file = agentRows();
+    const stream = streamed(step.events, file.rows);
+    step.item({ kind: "thinking", index: 0, text: "Hmm" });
+    step.item({ kind: "text", index: 1, text: "A" });
+    step.item(STOP);
+    await polls();
+    muchLater();
+    const failure = await stream.failure;
+    expect(failure).toMatchObject({ kind: "transient", message: expect.stringContaining("wrote no row") });
+  });
+
+  test("fails with the service's answer when the step ends without a stop chunk while a row is pending", async () => {
+    const step = channel();
+    const file = agentRows();
+    const stream = streamed(step.events, file.rows);
+    step.item({ kind: "thinking", index: 0, text: "Hmm" });
+    step.item({ kind: "text", index: 1, text: "A" });
+    step.done();
+    await polls();
+    muchLater();
+    expect(await stream.failure).toBe(SERVICE_ANSWER);
+  });
+});

