+import { TemplateError, type TemplateToken } from "./types.js";
+
+export type TemplateNode =
+  | { kind: "text"; value: string }
+  | { kind: "variable"; path: string; escaped: boolean }
+  | { kind: "if" | "each"; path: string; children: TemplateNode[] };
+
+type OpenToken = Extract<TemplateToken, { kind: "open" }>;
+
+/**
+ * Builds the nested block tree from tokens. Each closing tag matches the innermost open block.
+ * Throws TemplateError at the closing offset for an unexpected or mismatched closing tag,
+ * and at the opening offset of the innermost unclosed block when input ends early.
+ */
+export function parse(tokens: readonly TemplateToken[]): TemplateNode[] {
+  const root: TemplateNode[] = [];
+  const stack: { token: OpenToken; children: TemplateNode[] }[] = [];
+  for (const token of tokens) {
+    const children = stack.at(-1)?.children ?? root;
+    switch (token.kind) {
+      case "text":
+        children.push({ kind: "text", value: token.value });
+        break;
+      case "variable":
+        children.push({ kind: "variable", path: token.path, escaped: token.escaped });
+        break;
+      case "open": {
+        const block = { kind: token.block, path: token.path, children: [] };
+        children.push(block);
+        stack.push({ token, children: block.children });
+        break;
+      }
+      case "close": {
+        const open = stack.pop();
+        if (!open) throw new TemplateError(`Unexpected closing ${token.block} tag`, token.position);
+        if (open.token.block !== token.block) {
+          throw new TemplateError(
+            `Mismatched closing ${token.block} tag for open ${open.token.block} block`,
+            token.position,
+          );
+        }
+      }
+    }
+  }
+  const unclosed = stack.at(-1);
+  if (unclosed) throw new TemplateError(`Unclosed ${unclosed.token.block} block`, unclosed.token.position);
+  return root;
+}
