index 67d1ace..b25b9de 100644
--- a/render.ts
+++ b/render.ts
@@ -1,8 +1,53 @@
+import { parse, type TemplateNode } from "./parser.js";
 import { tokenize } from "./tokenizer.js";
 import type { TemplateContext } from "./types.js";

-export function render(template: string, _context: TemplateContext = {}): string {
-  return tokenize(template)
-    .map((token) => token.kind === "text" ? token.value : "")
-    .join("");
+/**
+ * Renders a template against a context. `{{path}}` is HTML-escaped, `{{{path}}}` is raw,
+ * `{{#if path}}` uses JavaScript truthiness, and `{{#each path}}` renders its body once per
+ * array item with that item as the body's context. Missing, null, and undefined values render
+ * as empty text. Throws TemplateError for malformed or unbalanced tags.
+ */
+export function render(template: string, context: TemplateContext = {}): string {
+  return renderNodes(parse(tokenize(template)), context);
+}
+
+function renderNodes(nodes: readonly TemplateNode[], context: unknown): string {
+  return nodes.map((node) => renderNode(node, context)).join("");
+}
+
+function renderNode(node: TemplateNode, context: unknown): string {
+  switch (node.kind) {
+    case "text":
+      return node.value;
+    case "variable": {
+      const value = resolve(context, node.path);
+      const text = value == null ? "" : String(value);
+      return node.escaped ? escapeHtml(text) : text;
+    }
+    case "if":
+      return resolve(context, node.path) ? renderNodes(node.children, context) : "";
+    case "each": {
+      const items = resolve(context, node.path);
+      return Array.isArray(items) ? items.map((item) => renderNodes(node.children, item)).join("") : "";
+    }
+  }
+}
+
+function resolve(context: unknown, path: string): unknown {
+  let value = context;
+  for (const segment of path.split(".")) {
+    if (value == null) return undefined;
+    value = (value as Record<string, unknown>)[segment];
+  }
+  return value;
+}
+
+function escapeHtml(text: string): string {
+  return text
+    .replaceAll("&", "&amp;")
+    .replaceAll("<", "&lt;")
+    .replaceAll(">", "&gt;")
+    .replaceAll('"', "&quot;")
+    .replaceAll("'", "&#39;");
 }
diff --git a/tokenizer.ts b/tokenizer.ts
index b05913a..a060fdb 100644
--- a/tokenizer.ts
+++ b/tokenizer.ts
@@ -1,7 +1,58 @@
-import type { TemplateToken } from "./types.js";
+import { TemplateError, type TemplateToken } from "./types.js";

+const BLOCKS = new Set(["if", "each"]);
+
+/**
+ * Splits a template into text, `{{path}}` (escaped), `{{{path}}}` (raw),
+ * `{{#if path}}` / `{{#each path}}` openings, and `{{/if}}` / `{{/each}}` closings.
+ * Every token's position is the zero-based offset of its first source character.
+ * Throws TemplateError at the tag's offset for an unterminated, empty, or unknown tag.
+ */
 export function tokenize(template: string): TemplateToken[] {
-  return template.length === 0
-    ? []
-    : [{ kind: "text", value: template, position: 0 }];
+  const tokens: TemplateToken[] = [];
+  let cursor = 0;
+  while (cursor < template.length) {
+    const start = template.indexOf("{{", cursor);
+    if (start === -1) {
+      tokens.push({ kind: "text", value: template.slice(cursor), position: cursor });
+      break;
+    }
+    if (start > cursor) {
+      tokens.push({ kind: "text", value: template.slice(cursor, start), position: cursor });
+    }
+    const raw = template.startsWith("{{{", start);
+    const [opener, closer] = raw ? ["{{{", "}}}"] : ["{{", "}}"];
+    const end = template.indexOf(closer, start + opener.length);
+    if (end === -1) throw new TemplateError("Unterminated tag", start);
+    const body = template.slice(start + opener.length, end).trim();
+    tokens.push(raw ? rawToken(body, start) : tagToken(body, start));
+    cursor = end + closer.length;
+  }
+  return tokens;
+}
+
+function rawToken(path: string, position: number): TemplateToken {
+  if (path.length === 0) throw new TemplateError("Empty tag", position);
+  return { kind: "variable", path, escaped: false, position };
+}
+
+function tagToken(body: string, position: number): TemplateToken {
+  if (body.startsWith("#")) {
+    const [block = "", ...rest] = body.slice(1).trim().split(/\s+/);
+    const path = rest.join(" ");
+    if (!isBlock(block)) throw new TemplateError(`Unknown block "${block}"`, position);
+    if (path.length === 0) throw new TemplateError(`Missing path for ${block} block`, position);
+    return { kind: "open", block, path, position };
+  }
+  if (body.startsWith("/")) {
+    const block = body.slice(1).trim();
+    if (!isBlock(block)) throw new TemplateError(`Unknown closing block "${block}"`, position);
+    return { kind: "close", block, position };
+  }
+  if (body.length === 0) throw new TemplateError("Empty tag", position);
+  return { kind: "variable", path: body, escaped: true, position };
+}
+
+function isBlock(name: string): name is "if" | "each" {
+  return BLOCKS.has(name);
 }
